def test_added_or_deleted_item_returns_false(self):
    shorter = DeltaReportBundleArchive((self.full, self.first))
    longer = DeltaReportBundleArchive(
        (
            self.full,
            self.first,
            self.second,
            DeltaReportBundleArchive((self.full,)).items[0],
        )
    )
    self.assertFalse(
        verify_delta_report_bundle_archive_seal(
            DeltaReportBundleArchiveSeal(
                shorter, self.seal.signature
            ),
            self.key,
        )
    )
    self.assertFalse(
        verify_delta_report_bundle_archive_seal(
            DeltaReportBundleArchiveSeal(
                longer, self.seal.signature
            ),
            self.key,
        )
    )

def test_substituted_item_returns_false(self):
    # Re-seal a different archive under the same key, then graft its
    # item into the signed archive: the archive verifies structurally,
    # but the signature binds the original encoding.
    substitute_archive = DeltaReportBundleArchive((self.first,))
    sub_seal = make_seal(substitute_archive, self.key, seed=520)
    self.assertTrue(
        verify_delta_report_bundle_archive_seal(sub_seal, self.key)
    )
    replaced = DeltaReportBundleArchive(
        (self.full, self.first, sub_seal.archive.items[0])
    )
    # Two identical items in a row is still a legal non-empty archive;
    # its digest differs from the signed one.
    replaced = DeltaReportBundleArchive(
        (self.second, self.first, self.full)
    )
    self.assertNotEqual(replaced, self.archive)
    self.assertFalse(
        verify_delta_report_bundle_archive_seal(
            DeltaReportBundleArchiveSeal(
                replaced, self.seal.signature
            ),
            self.key,
        )
    )

